        static float[] Floats(string hex) => Array.ConvertAll(hex.Split(','), h => BitConverter.Int32BitsToSingle(Convert.ToInt32(h, 16)));
        static Vector3 V3(string hex) { var f = Floats(hex); return new Vector3(f[0], f[1], f[2]); }
        static Vector2 V2(string hex) { var f = Floats(hex); return new Vector2(f[0], f[1]); }
        static Quaternion Q(string hex) { var f = Floats(hex); return new Quaternion(f[0], f[1], f[2], f[3]); }
        static string Hex(float f) => BitConverter.SingleToInt32Bits(f).ToString("x8");
        static string Hex(Vector3 v) => Hex(v.x) + "," + Hex(v.y) + "," + Hex(v.z);
        static string Hex(Quaternion q) => Hex(q.x) + "," + Hex(q.y) + "," + Hex(q.z) + "," + Hex(q.w);
        static string Rows(Matrix4x4 m)
        {
            var s = new string[12];
            for (int r = 0; r < 3; r++)
                for (int c = 0; c < 4; c++)
                    s[r * 4 + c] = Hex(m[r, c]);
            return string.Join(",", s);
        }

        /// World matrix, rotation and lossy scale at every level, bit for bit (signed zeros
        /// included), for chains with rotations, non-uniform, negative and zero scales.
        [Fact]
        public void WorldValuesMatchTheOriginalBitForBit()
        {
            foreach (var chain in Chains)
            {
                Transform parent = null;
                var root = (Transform)null;
                foreach (var level in chain)
                {
                    var f = level.Split(';');
                    var t = new GameObject("level").transform;
                    root ??= t;
                    if (parent != null) t.SetParent(parent, false);
                    t.localPosition = V3(f[0]);
                    t.localRotation = Q(f[1]);
                    t.localScale = V3(f[2]);
                    Assert.Equal(f[3], Rows(t.localToWorldMatrix));
                    Assert.Equal(f[4], Hex(t.rotation));
                    Assert.Equal(f[5], Hex(t.lossyScale));
                    parent = t;
                }
                UnityEngine.Object.DestroyImmediate(root.gameObject);
            }
        }

        /// The same composition for RectTransforms, and GetWorldCorners through it.
        [Fact]
        public void RectTransformMatricesAndCornersMatchTheOriginal()
        {
            RectTransform parent = null;
            foreach (var level in RectChain)
            {
                var f = level.Split(';');
                var t = (RectTransform)new GameObject("rect", typeof(RectTransform)).transform;
                if (parent != null) t.SetParent(parent, false);
                t.anchorMin = V2(f[0]);
                t.anchorMax = V2(f[1]);
                t.pivot = V2(f[2]);
                t.sizeDelta = V2(f[3]);
                t.anchoredPosition = V2(f[4]);
                t.localPosition = V3(f[5]);
                t.localRotation = Q(f[6]);
                t.localScale = V3(f[7]);
                Assert.Equal(f[8], Rows(t.localToWorldMatrix));
                var corners = new Vector3[4];
                t.GetWorldCorners(corners);
                Assert.Equal(f[9], string.Join(",", Array.ConvertAll(corners, Hex)));
                parent = t;
            }
        }

        /// The localRotation setter's normalization, bit for bit.
        [Fact]
        public void LocalRotationIsNormalizedAsTheOriginalDoes()
        {
            var t = new GameObject("q").transform;
            foreach (var pair in Normalized)
            {
                var f = pair.Split(';');
                t.localRotation = Q(f[0]);
                Assert.Equal(f[1], Hex(t.localRotation));
            }
        }
